  validate: async (formValue) => {
    if (formValue.test1.length > formValue.test.length) {
      return {
        type: 'formError',
        message: 'something is wrong here',
      };
    }

    if (formValue.test === 'test') {
      return 'direct error message';
    }

    return true;
  },
